    # Flood fill from all boundary cells that are 0 (background)
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                if input_grid[r][c] == 0:
                    outside[r][c] = True
                    queue.append((r,c))

    visited_ext = [[False]*cols for _ in range(rows)]

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if not visited_ext[nr][nc] and input_grid[nr][nc] == 0:
                    visited_ext[nr][nc] = True
                    queue.append((nr, nc))

    for r in range(rows):
        for c in range(cols):
            if visited_ext[r][c]:
                outside[r][c] = True

    # Now for each cell inside an enclosure
    for r in range(rows):
        for c in range(cols):
            if not outside[r][c] and output[r][c] == 1:
                # Find connected 1s in this enclosure
                queue = deque([(r,c)])
                visited_enc = {(r,c)}

                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nc = cr+dr, cc+dc
                        if (nc[0], nc[1]) not in visited_enc:
