                    if output[pr][pc] not in (0, 1):
                        special_values.add(output[pr][pc])

                if special_values:
                    for pr, pc in visited_enc:
                        if output[pr][pc] == 1:
                            output[pr][pc] = list(special_values)[0]

    return output

