            if input_grid[r][c] == 0:
                zeros.add((r,c))

    # Step 2: For each 1, find minimum distance to any 0
    # Using BFS from all 0s simultaneously
    distance_to_zero = [[float('inf')]*cols for _ in range(rows)]

    # Start BFS from all 0s
    queue = deque()
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 0:
                distance_to_zero[r][c] = 0
                queue.append((r,c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and input_grid[nr][nc] == 1:
                if distance_to_zero[nr][nc] == float('inf'):
                    distance_to_zero[nr][nc] = distance_to_zero[r][c] + 1
                    queue.append((nr, nc))

    # Step 3: Interior 1s are those with distance >= 2 to any 0
    # (1 cell away = boundary, 2+ cells away = interior)
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 1 and distance_to_zero[r][c] >= 2:
                # This is an interior 1
                # Find connected interior region
                visited_region = set()
                queue_region = deque([(r,c)])

                while queue_region:
                    rr, cc = queue_region.popleft()
                    if (rr, cc) in visited_region:
                        continue
                    visited_region.add((rr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited_region:
                                if input_grid[nr][nc] == 1 and distance_to_zero[nr][nc] >= 2:
                                    visited_region.add((nr, nc))
                                    queue_region.append((nr, nc))

                # Find special value in this interior region
                special = set()
                for rr, cc in visited_region:
                    if output[rr][cc] not in (0, 1):
                        special.add(output[rr][cc])

                if special:
                    val = list(special)[0]
                    for rr, cc in visited_region:
                        output[rr][cc] = val

    return output

