from collections import deque

def solve_correct(input_grid):
    G = input_grid
    rows = len(G)
    cols = len(G[0])

    # Find all 0 cells
    zeros = set()
    for r in range(rows):
        for c in range(cols):
            if G[r][c] == 0:
                zeros.add((r,c))

    # Find all component cells that才有可能 be interior
    # Component cells are 1s

    # Step 1: Find boundary 1s (touching any 0)
    boundaries = set()
    for r in range(rows):
        for c in range(cols):
            if G[r][c] == 1:
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if (nr, nc) in zeros:
                        boundaries.add((r,c))
                        break

    # Step 2: Find all corner-connected components of 1s
    components = []
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if G[r][c] == 1 and (r,c) not in visited:
                comp = set()
                q = deque([(r,c)])
                visited.add((r,c))
                comp.add((r,c))
                while q:
                    rr, cc = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and G[nr][nc] == 1:
                            if (nr, nc) not in visited:
                                visited.add((nr, nc))
                                comp.add((nr, nc))
                                q.append((nr, nc))
                components.append(comp)

    # Step 3: For each component, find interior (cells not reachable from boundary via 1s)
    component_interiors = []
    for comp in components:
        # Start BFS from all boundary cells in this component
        q = deque()
        comp_boundaries_in_comp = set()
        for cell in comp:
            if cell in boundaries:
                comp_boundaries_in_comp.add(cell)
                q.append(cell)

        visited_comp = set()
        for rb in comp_boundaries_in_comp:
            visited_comp.add(rb)

        # BFS within component
        while q:
            (br, bc) = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = br+dr, bc+dc
                if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) in comp:
                    if (nr, nc) not in visited_comp:
                        visited_comp.add((nr, nc))
                        q.append((nr, nc))

        # Interior cells: component cells not in visited_comp
        interior = comp - visited_comp

        component_interiors.append(comp)  # For reference
        component_interiors.append(boundaries and interior)

    # Step 4: Fill each interior with its "dominant" special value
    output = [row[:] for row in G]
    for comp, interior in zip(components, component_interiors):
        if comp and interior:
            # Find special values in this component
            special = set()
            for cell in comp:
                if output[cell[0]][cell[1]] not in (0, 1):
                    special.add(output[cell[0]][cell[1]])

            if special:
                # Use the first special value found as the fill value
                fill_val = list(special)[0]
                for cell in interior:
                    output[cell[0]][cell[1]] = fill_val

    return output

